"js": "\nconst live = typeof window !== \"undefined\";\nconst root = this;\n// the published page hands over component.component_data, the editor canvas the whole component\nconst data = (component_data && component_data.component_data) || component_data || {};\nconst days = data.days || [];\nconst sum = root.querySelector(\".ys-ticket-sum\");\nconst said = root.querySelector(\".ys-ticket-said\");\nconst labels = Array.from(root.querySelectorAll(\".ys-day\"));\n// the canvas keeps both server variants of each radio: tick the first day's only\nlabels.forEach((label, i) => label.querySelectorAll(\"input\").forEach((input) => { input.checked = i === 0; }));\n// the total swaps in place, no roll; the hidden live region says the whole line once per pick\nconst paint = (announce) => {\n  let i = labels.findIndex((label) => !!label.querySelector(\"input:checked\"));\n  if (i < 0) i = 0;\n  const day = days[i];\n  if (!day) return;\n  if (sum) sum.textContent = day.total;\n  if (announce && said) said.textContent = String(data.job_name || \"\") + \", \" + String(day.label || \"\").toLowerCase() + \": \" + day.total + \".\";\n};\npaint(false);\nif (!live) return;\n\nconst settle = () => requestAnimationFrame(() => requestAnimationFrame(() => { root.dataset.settled = \"\"; }));\nif (document.readyState === \"loading\") document.addEventListener(\"DOMContentLoaded\", settle, { once: true });\nelse settle();\nconst unsettle = () => { document.removeEventListener(\"DOMContentLoaded\", settle); delete root.dataset.settled; };\n\nconst onChange = () => paint(true);\nroot.addEventListener(\"change\", onChange);\nreturn () => { root.removeEventListener(\"change\", onChange); unsettle(); };\n"
