def split_rows(raw):
	if isinstance(raw, str):
		try:
			raw = json.loads(raw)
		except Exception:
			raw = [raw]
	out = []
	for item in raw or []:
		parts = []
		for part in str(item).split("|"):
			parts.append(part.strip())
		if parts and parts[0]:
			out.append(parts)
	return out


def num(value):
	try:
		text = str(value).replace(",", "").replace("$", "").replace("%", "").strip()
		if not text:
			return None
		return float(text)
	except Exception:
		return None


def money(value, cur):
	digits = str(int(round(value)))
	out = ""
	while len(digits) > 3:
		out = "," + digits[-3:] + out
		digits = digits[:-3]
	return cur + digits + out


def slugify(text):
	out = ""
	for ch in str(text or "").lower():
		out = out + (ch if ch.isalnum() else "-")
	return out


def fixed(value):
	return str(round(value, 2))

cur = str(props.get("currency") or "$")
base = num(props.get("base_price")) or 0
job_name = str(props.get("job_name") or "")
days = []
for parts in split_rows(props.get("days")):
	add = num(parts[2]) if len(parts) > 2 else 0
	if add is None:
		add = 0
	first = len(days) == 0
	days.append({
		"label": parts[0],
		"note": parts[1] if len(parts) > 1 else "",
		"value": str(int(round(add))),
		"total": money(base + add, cur),
		"checked": first,
		"unchecked": not first,
	})
component.days = days
component.total = money(base, cur)
if days:
	component.total = days[0]["total"]
component.job_name = job_name
component.job_line = job_name + ", " + str(props.get("price_word") or "fixed")
component.job_slug = str(props.get("job") or "")
component.component_data = {"days": days, "job_name": job_name}
